INSERT INTO m243_art VALUES
(0,0,$m243$الديباجة$m243$,$m243$قانون رقم 120 لسنة 2008 بإصدار قانون بإنشاء المحاكم الاقتصادية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب ووافق مجلس الشورى على القانون الآتى نصه ، وقد أصدرناه :$m243$,'4d733fe0251db73a6df3e195fe5b01ce'),
(1,-1,$m243$المادة الأولى إصدار$m243$,$m243$يعمل بأحكام القانون المرافق فى شأن المحاكم الاقتصادية ، ولا يسرى فى شأنه أى حكم يخالف أحكامه .$m243$,'10c6f57fc14a0c3da5b7abe3ff7eb037'),
(2,-1,$m243$المادة الثانية إصدار$m243$,$m243$تحيل المحاكم من تلقاء نفسها ما يوجد لديها من منازعات ودعاوى أصبحت بمقتضى أحكام هذا القانون من اختصاص المحاكم الاقتصادية وذلك بالحالة التى تكون عليها وبدون رسوم ، وفى حالة غياب أحد الخصوم يقوم قلم الكتاب بإعلانه بأمر الإحالة مع تكليفه بالحضور فى الميعاد أمام المحكمة التى أحيلت إليها الدعوى .
وتفصل المحاكم الاقتصادية فيما يحال إليها تطبيقاً لأحكام الفقرة السابقة دون عرضها على هيئة التحضير والوساطة المنصوص عليها فى المادة (8) من القانون المرافق .
كما تحال الطعون التى أصبحت من اختصاص المحاكم المنصوص عليها فى المادة (12) من هذا القانون إلى تلك المحاكم الأخيرة ، وذلك بالحالة التى تكون عليها .
ولا تسرى أحكام الفقرتين الأولى والثالثة من هذه المادة على المنازعات والدعاوى والطعون المحكوم فيها ، أو المؤجلة للنطق بالحكم قبل تاريخ العمل بهذا القانون ، وتبقى الأحكام الصادرة فيها خاضعة للقواعد المنظمة لطرق الطعن السارية فى تاريخ صدورها .$m243$,'224c93aecd83ee73d37923d1552ff86d'),
(3,-1,$m243$المادة الثالثة إصدار$m243$,$m243$تستمر محكمة النقض ومحاكم الاستئناف والدوائر الاستئنافية فى المحاكم الابتدائية فى نظر الطعون المرفوعة أمامها ، قبل تاريخ العمل بهذا القانون ، عن الأحكام الصادرة فى المنازعات والدعاوى المشار إليها فى الفقرة الأولى من المادة الثانية .$m243$,'f5989224972fb0fb49945ea4fca80066'),
(4,-1,$m243$المادة الرابعة إصدار$m243$,$m243$تطبق أحكام قوانين الإجراءات الجنائية ، وحالات وإجراءات الطعن أمام محكمة النقض ، والمرافعات المدنية والتجارية والإثبات فى المواد المدنية والتجارية، وذلك فيما لم يرد بشأنه نص خاص فى القانون المرافق .$m243$,'b39b587f94e1a5c3765e569a2093a188'),
(5,-1,$m243$المادة الخامسة إصدار$m243$,$m243$يصدر وزير العدل ، بالتنسيق مع وزير الاتصالات وتكنولوجيا المعلومات ، القرارات المنظمة للقيد فى السجل المشار إليه فى المادة (17) من القانون المرافق وتنظيم إقامة وسير الدعوى إلكترونياً وإعلانها وطرق حمايتها وربط المحاكم الاقتصادية إلكترونياً ، وتلتزم الجهات ذات الصلة بتنفيذها .
كما يصدر وزير العدل ، بناءً على الطلبات التى تقدم من راغبى القيد ممن ترشحهم الجهات الرقابية المختصة أو الغرف والاتحادات والجمعيات وغيرها من الكيانات المعنية بشئون المال والتجارة والصناعة ، قراراً ينظم القيد فى الجداول المشار إليها فى الفقرة الثانية من المادة (8) من هذا القانون .$m243$,'c92f4a0096a81d6e1ba84a78b6029057'),
(6,-1,$m243$المادة السادسة إصدار$m243$,$m243$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتباراً من أول أكتوبر سنة 2008
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 17 جمادى الأولى سنة 1429 هـ .
(الموافق 22 مايو سنة 2008 م) .
حسنى مبارك$m243$,'4f602a40ccb6e5f8750a23e135831efb'),
(1,0,$m243$المادة 1$m243$,$m243$تنشأ بدائرة اختصاص كل محكمة استئناف محكمة تسمى «المحكمة الاقتصادية» ينتدب لرئاستها رئيس بمحاكم الاستئناف لمدة سنة قابلة للتجديد بقرار من وزير العدل بعد موافقة مجلس القضاء الأعلى ، ويكون قضاتها من بين قضاة المحاكم الابتدائية ومحاكم الاستئناف يصدر باختيارهم قرار من مجلس القضاء الأعلى .
وتتشكل المحكمة الاقتصادية من دوائر ابتدائية ودوائر استئنافية ودوائر الجنايات الاقتصادية بدرجتيها ، ويصدر بتعيين مقار هذه الدوائر قرار من وزير العدل بعد أخذ رأى مجلس القضاء الأعلى .
وتنعقد الدوائر الابتدائية والاستئنافية ودوائر الجنايات الاقتصادية بدرجتيها المنصوص عليها فى الفقرة السابقة فى مقار المحاكم الاقتصادية ، ويجوز أن تنعقد ، عند الضرورة ، فى أى مكان آخر وذلك بقرار من وزير العدل بناءً على طلب رئيس المحكمة الاقتصادية .$m243$,'547cffbd32e456ec9f64f9b2c97816be'),
(2,0,$m243$المادة 2$m243$,$m243$تشكل كل دائرة من الدوائر الابتدائية الاقتصادية من ثلاثة من الرؤساء بالمحاكم الابتدائية .
وتشكل كل دائرة من الدوائر الاستئنافية من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة نائب رئيس بمحكمة الاستئناف .
وتشكل كل دائرة من دوائر جنايات أول درجة الاقتصادية من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة نائب رئيس بمحكمة الاستئناف .
كما تشكل كل دائرة من دوائر الجنايات الاقتصادية المستأنفة من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة رئيس بمحكمة الاستئناف .$m243$,'6d7973a6ea1944db4cd007b6db113a88'),
(3,0,$m243$المادة 3$m243$,$m243$تعين الجمعية العامة للمحكمة الاقتصادية ، فى بداية كل عام قضائى ، قاضياً أو أكثر من قضاتها بدرجة رئيس بالمحاكم الابتدائية من الفئة (أ) على الأقل ، ليحكم ، بصفة مؤقتة ومع عدم المساس بأصل الحق ، فى المسائل المستعجلة التى يخشى عليها من فوات الوقت والتى تختص بها تلك المحكمة .
ويصدر القاضى المشار إليه فى الفقرة الأولى الأوامر على عرائض والأوامر الوقتية ، وذلك فى المسائل التى تختص بها المحكمة الاقتصادية .
كما يصدر ، وأياً كانت قيمة الحق محل الطلب ، أوامر الأداء فى تلك المسائل ، وفى حالة امتناعه يحدد جلسة لنظر الدعوى أمام إحدى الدوائر الابتدائية أو الاستئنافية بالمحكمة ، بحسب الأحوال .$m243$,'e1d36a9b5db86eb0151a683ad7ac2e82'),
(4,0,$m243$المادة 4$m243$,$m243$مع عدم الإخلال بالاختصاصات المقررة للمحاكم الاقتصادية المنصوص عليها فى أى قانون آخر ، تختص المحاكم الاقتصادية بدوائرها الابتدائية والاستئنافية ودوائر الجنايات الاقتصادية بدرجتيها ، دون غيرها ، نوعياً ومكانياً بنظر الدعاوى الجنائية الناشئة عن الجرائم المنصوص عليها فى القوانين الآتية :
1 - قانون العقوبات فى شأن جرائم المسكوكات والزيوف المزورة .
2 - قانون الإشراف والرقابة على التأمين فى مصر .
3 - قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد .
4 - قانون سوق رأس المال .
5 - قانون تنظيم نشاطى التأجير التمويلى والتخصيم .
6 - قانون الإيداع والقيد المركزى للأوراق المالية .
7 - قانون التمويل العقارى .
8 - قانون حماية حقوق الملكية الفكرية .
9 - قانون البنك المركزى والجهاز المصرفى والنقد .
10 - قانون الشركات العاملة فى مجال تلقى الأموال لاستثمارها .
11 - قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس .
12 - قانون حماية الاقتصاد القومى من الآثار الناجمة عن الممارسات الضارة فى التجارة الدولية .
13 - قانون حماية المنافسة ومنع الممارسات الاحتكارية .
14 - قانون حماية المستهلك .
15 - قانون تنظيم الاتصالات .
16 - قانون تنظيم التوقيع الإلكترونى وإنشاء هيئة تنمية صناعة تكنولوجيا المعلومات .
17 - قانون مكافحة غسل الأموال .
18 - قانون تنظيم الضمانات المنقولة .
19 - قانون تنظيم نشاط التمويل متناهى الصغر .
20 - قانون الاستثمار .
21 - قانون مكافحة جرائم تقنية المعلومات .$m243$,'192a45b484ca3561f5f8a4b355c860c3'),
(5,0,$m243$المادة 5$m243$,$m243$تختص الدوائر الابتدائية بالمحاكم الاقتصادية بنظر قضايا الجنح المنصوص عليها فى القوانين المشار إليها فى المادة (4) من هذا القانون ، ويكون استئنافها أمام الدوائر الاستئنافية بالمحاكم الاقتصادية ، على أن تسرى على الطعون فى الأحكام الصادرة من الدوائر الابتدائية بالمحاكم الاقتصادية فى مواد الجنح المواعيد والإجراءات ، وأحكام النفاذ المعجل المقررة فى قانون الإجراءات الجنائية .
وتختص دوائر جنايات أول درجة الاقتصادية بالنظر ابتداءً فى قضايا الجنايات المنصوص عليها فى القوانين المشار إليها فى المادة (4) من هذا القانون ، ويكون استئنافها أمام دوائر الجنايات الاقتصادية المستأنفة ، على أن تسرى على الطعون فى الأحكام الصادرة من دوائر جنايات أول درجة الاقتصادية فى مواد الجنايات المواعيد والإجراءات المقررة فى قانون الإجراءات الجنائية .$m243$,'5d96e3b4d16bec1ebf316d6537340520'),
(6,0,$m243$المادة 6$m243$,$m243$فيما عدا المنازعات والدعاوى التى يختص بها مجلس الدولة ، تختص الدوائر الابتدائية بالمحاكم الاقتصادية ، دون غيرها ، بنظر المنازعات والدعاوى التى لا تجاوز قيمتها خمسة عشر مليون جنيه ، والتى تنشأ عن تطبيق القوانين الآتية :
1 - قانون الشركات العاملة فى مجال تلقى الأموال لاستثمارها الصادر بالقانون رقم 146 لسنة 1988
2 - قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992
3 - قانون تنظيم نشاطى التأجير التمويلى والتخصيم الصادر بالقانون رقم 176 لسنة 2018
4 - القانون رقم 161 لسنة 1998 بشأن حماية الاقتصاد القومى من الآثار الناجمة عن الممارسات الضارة فى التجارة الدولية .
5 - قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ، وذلك فى شأن نقل التكنولوجيا والوكالة التجارية وعمليات البنوك ، وكذلك المنازعات والدعاوى الأخرى الناشئة عن تطبيق القانون ذاته إذا جاوزت قيمتها عشرة ملايين جنيه .
6 - قانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001
7 - قانون حماية حقوق الملكية الفكرية الصادر بالقانون رقم 82 لسنة 2002
8 - قانون تنظيم الاتصالات الصادر بالقانون رقم 10 لسنة 2002
9 - القانون رقم 15 لسنة 2004 بتنظيم التوقيع الإلكترونى وبإنشاء هيئة تنمية صناعة تكنولوجيا المعلومات .
10 - قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005
11 - قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981
12 - قانون البنك المركزى والجهاز المصرفى الصادر بالقانون رقم 194 لسنة 2020
13 - قانون التجارة البحرية الصادر بالقانون رقم 8 لسنة 1990
14 - قانون الطيران المدنى الصادر بالقانون رقم 28 لسنة 1981 ، وذلك فى شأن نقل البضائع والركاب .
15 - قانون حماية المستهلك الصادر بالقانون رقم 181 لسنة 2018
16 - قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015
17 - قانون المناطق الاقتصادية ذات الطبيعة الخاصة الصادر بالقانون رقم 83 لسنة 2002
18 - القانون رقم 141 لسنة 2014 بتنظيم مزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر .
19 - قانون الاستثمار الصادر بالقانون رقم 72 لسنة 2017
20 - القانون رقم 175 لسنة 2018 فى شأن مكافحة جرائم تقنية المعلومات .
كما تختص بالنظر فى دعاوى التعويض أو التأمين الناشئة عن تطبيق أحكام القوانين المشار إليها بالفقرة الأولى من هذه المادة ، بحسب الأحوال .
ويكون الحكم الصادر فى الدعاوى المشار إليها فى الفقرتين الأولى والثانية من هذه المادة انتهائياً إذا كانت قيمة الدعوى لا تجاوز سبعمائة وخمسين ألف جنيه .
وتختص الدوائر الاستئنافية فى المحاكم الاقتصادية ، دون غيرها ، بالنظر ابتداءً فى جميع المنازعات والدعاوى المنصوص عليها فى الفقرات الأولى والثانية والثالثة من هذه المادة إذا جاوزت قيمتها خمسة عشر مليون جنيه أو كانت الدعوى غير مقدرة القيمة .
وتختص الدوائر الابتدائية والاستئنافية بالمحاكم الاقتصادية التى أصدرت الأمر بنظر تظلمات ودعاوى الرسوم القضائية الناشئة عن تطبيق أحكام هذا القانون والقرارات الصادرة من قضاة المحكمة .$m243$,'22dcc66d585cceadd25f2605f1258a83'),
(7,0,$m243$المادة 7$m243$,$m243$تختص الدائرة الابتدائية بالمحكمة الاقتصادية دون غيرها بالفصل فى المسائل الآتية :
1 - منازعات التنفيذ الوقتية والموضوعية عن الأحكام والأوامر التى تصدرها المحكمة .
2 - الدعاوى المتعلقة والناشئة عن قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس .
ويطعن فى الأحكام الصادرة فى المسائل المتقدمة أمام الدائرة الاستئنافية بالمحكمة الاقتصادية .$m243$,'4c8973d6969a23798f58a9a4c89303a8'),
(7,1,$m243$المادة 7 مكرراً$m243$,$m243$تعين الجمعية العامة لكل محكمة اقتصادية فى بداية كل عام قضائى قاضياً أو أكثر من قضاتها بدرجة رئيس بالمحاكم الابتدائية من الفئة (أ) على الأقل ، ويعاونه عدد كاف من معاونى التنفيذ والموظفين يصدر بتحديدهم قرار من رئيس المحكمة الاقتصادية ، ويختص بالإشراف على إجراءات التنفيذ المتعلقة بالسندات التنفيذية الصادرة من تلك المحكمة ، كما يختص بإصدار القرارات والأوامر الصادرة على العرائض المتعلقة بالتنفيذ وذلك فى المسائل التى تختص بها المحكمة الاقتصادية ، ويتم التظلم من القرارات والأوامر الصادرة منه أمام الدوائر الابتدائية بالمحاكم الاقتصادية ، ويعتبر الحكم الصادر فى التظلم نهائياً .$m243$,'c00e71d9b34e02355ca5eb602b16e3ab'),
(7,2,$m243$المادة 7 مكرراً (أ)$m243$,$m243$يعد بالمحكمة الاقتصادية سجل خاص تقيد فيه طلبات التنفيذ التى تقدم إلى قاضى التنفيذ ، وينشأ لكل طلب ملف تودع به جميع الأوراق المتعلقة بهذه الطلبات ، ويعرض الملف على قاضى التنفيذ عقب كل إجراء ، ويثبت به ما يصدره من قرارات وأوامر ، وما قد تصدره الدائرة الابتدائية من أحكام فى منازعات التنفيذ الموضوعية والوقتية .$m243$,'8647f78e51f446d257dd0e6325c67c0f'),
(7,3,$m243$المادة 7 مكرراً (ب)$m243$,$m243$يجرى التنفيذ بواسطة معاونى التنفيذ بناءً على طلب ذوى الشأن متى سلم السند التنفيذى إلى قاضى التنفيذ المختص .
فإذا امتنع معاون التنفيذ عن القيام بأى إجراء من إجراءات التنفيذ ، كان لصاحب الشأن أن يرفع الأمر بعريضة إلى قاضى التنفيذ .
وإذا وقعت مقاومة أو تعد على معاون التنفيذ ، وجب عليه أن يتخذ جميع الوسائل التحفظية ، وله فى سبيل ذلك بعد عرض الأمر على قاضى التنفيذ ، أن يطلب معونة القوة العامة والسلطة المحلية .$m243$,'8361733cfaf7ec82dd4d1fd63b2f90e4'),
(8,0,$m243$المادة 8$m243$,$m243$تنشأ بكل محكمة اقتصادية هيئة تسمى «هيئة التحضير والوساطة» ، يشار إليها فى هذا القانون بالهيئة ، وتتولى التحضير والوساطة فى الدعاوى التى تختص بها هذه المحكمة وذلك فيما عدا الدعاوى الجنائية والدعاوى المستأنفة والدعاوى والأوامر المنصوص عليها فى المادتين (3) و(7) من هذا القانون وكذلك الدعاوى المحالة إليها من المحاكم الأخرى للاختصاص النوعى .
وتشكل الهيئة برئاسة قاض من بين قضاة الدوائر الاستئنافية بالمحكمة الاقتصادية ، يشار إليه فى مواد هذا القانون برئيس الهيئة ، وعضوية عدد كاف من قضاتها بدرجة رئيس محكمة بالمحاكم الابتدائية على الأقل ، يشار إليهم فى مواد هذا القانون بقاضى التحضير ، تختارهم جمعيتها العامة فى بداية كل عام قضائى ، ويلحق بالهيئة العدد اللازم من الإداريين والكتبة ، ولها أن تستعين بمن ترى من الخبراء والمتخصصين المقيدين فى الجداول التى تعد لهذا الغرض بوزارة العدل .$m243$,'932178e445affdcbdb554c47433425b0'),
(8,1,$m243$المادة 8 مكرراً$m243$,$m243$يختص قاضى التحضير بالتحقق من استيفاء كافة المستندات اللازمة لتهيئة الدعوى للفصل فيها ودراستها ، وله عقد جلسات الاستماع ، والوساطة فى المنازعات والدعاوى .$m243$,'4db1b9191bacd17ae5841b7f5db789f5'),
(8,2,$m243$المادة 8 مكرراً (أ)$m243$,$m243$يخطر قاضى التحضير الخصوم بالحضور أمام الهيئة بأى وسيلة يراها مناسبة ، ومن بينها ، البريد الإلكترونى أو الاتصال الهاتفى أو الرسائل النصية ، وتعتبر الخصومة منعقدة فى حالة حضور المدعى عليه أو من يمثله قانوناً ، فإذا تخلف أحد الخصوم عن تقديم مستند له مسوغ فى الأوراق بعد طلبه منها ، جاز لقاضى التحضير تغريمه بغرامة لا تقل عن مائتى جنيه ولا تجاوز خمسمائة جنيه .$m243$,'9a81e9f12ab47bfc2f798fa914c91873'),
(8,3,$m243$المادة 8 مكرراً (ب)$m243$,$m243$لقاضى التحضير عقد جلسة أو عدة جلسات بين الأطراف منفردين أو مجتمعين يراعى فيها الالتزام بالقواعد والأعراف المقررة فى هذا الشأن ، وتعتبر هذه الجلسات سرية ، ولا يجوز الاحتجاج بها أو بما تم فيها من تنازلات من أطراف النزاع أمام أى محكمة أو جهة أخرى .$m243$,'11df4d6f8fcc1dbd9bd6f91aa942689b'),
(8,4,$m243$المادة 8 مكرراً (ج)$m243$,$m243$يتولى قاضى التحضير تحضير الدعوى خلال مدة لا تجاوز ثلاثين يوماً من تاريخ قيدها ، ويعرض على الأطراف تسوية النزاع بصورة ودية ، فإذا وافقه الخصوم تولى الوساطة بينهم فى خلال مدة لا تجاوز ثلاثين يوماً أخرى يجوز مدها لمدة مماثلة بموافقة رئيس الهيئة ، فإذا توصل قاضى التحضير إلى تسوية النزاع يحرر اتفاقاً بذلك يوقع عليه أطرافه ، ويعرض على رئيس الهيئة للتصديق عليه ، وفى هذه الحالة تكون له قوة السند التنفيذى ، أما إذا لم يوافق الخصوم على التسوية ، تحدد جلسة موضوعية لنظرها أمام الدائرة المختصة ، ويكلف المدعى بالإعلان .$m243$,'6933af1e5f003857f146e094d819e51a'),
(8,5,$m243$المادة 8 مكرراً (د)$m243$,$m243$للمحكمة المختصة بنظر الموضوع ابتداء فى أى حالة كانت عليها الدعوى أن توقف نظرها وتحيلها مرة أخرى إلى الهيئة ، بناء على طلب الخصوم ، لمحاولة الصلح بين الأطراف ، وتحدد المحكمة أجلا لذلك لا يجاوز ثلاثين يوماً ، يجوز لها مدها مرة واحدة لمدة مماثلة .
ويباشر قاضى التحضير عمله على النحو المبين بالمادة (8 مكرراً «ب») من هذا القانون .
فإذا توصل إلى الصلح ، يحرر اتفاقاً بذلك يلحق بمحضر جلسة نظر الدعوى للقضاء فيها وفق أحكام قانون المرافعات المدنية والتجارية ، أما إذا تعذر الصلح يحرر مذكرة بما اتخذه من إجراءات ويعرضها على المحكمة مرة أخرى للفصل فى الموضوع .$m243$,'c9c98d9611517a8be901c95a5d22db23'),
(8,6,$m243$المادة 8 مكرراً (هـ)$m243$,$m243$يتولى رئيس الهيئة ، بناءً على طلب من أحد الأطراف أو من تلقاء نفسه ، تصحيح ما يرد فى محاضر التسوية من أخطاء مادية .$m243$,'bbcb0edb98b4ef503b2fb1263547f58e'),
(8,7,$m243$المادة 8 مكرراً (و)$m243$,$m243$يجوز لأطراف النزاع الذى تختص بنظره المحاكم الاقتصادية اللجوء مباشرة إلى رئيس الهيئة بالمحكمة المختصة محلياً ، لتسوية النزاع وديا دون إقامة دعوى فى شأنه ، وفى هذه الحالة يسدد رسم لا يقل عن ألفى جنيه ولا يجاوز مائتى ألف جنيه تحدد فئاته بقرار من وزير العدل .
ويتولى قاضى التحضير الوساطة بين الأطراف على النحو المشار إليه سلفاً ، ويوقف تقادم الدعاوى الخاصة بتلك المنازعات أثناء مباشرة تلك الإجراءات .
فإذا توصل إلى تسوية النزاع وديا يحرر اتفاق تسوية على النحو المبين بالمادة (8 مكرراً «ج») من هذا القانون تكون له قوة السند التنفيذى ، أما إذا تعذر تسوية النزاع وديا ، يقوم قاضى التحضير بحفظ الطلب ورد جميع المستندات إلى الخصوم .$m243$,'d0e0c4d06c6a2f45b9ca7017eee2b6cd'),
(8,8,$m243$المادة 8 مكرراً (ز)$m243$,$m243$يمتنع على قاضى التحضير نظر الدعاوى التى سبق أن باشر إجراءات الوساطة فيها .
ويجوز لقاضى التحضير ولذوى الشأن فى حالة وجود مانع من مباشرته لإجراءات التحضير والوساطة التقدم بطلب إلى رئيس الهيئة للنظر فى استبدال آخر به ، وعلى رئيس الهيئة البت فى الطلب خلال ثلاثة أيام على الأكثر من تاريخ تقديمه .$m243$,'4b3dc3385d78a615a78f09ab5dcbc20f'),
(9,0,$m243$المادة 9$m243$,$m243$للدوائر الابتدائية والدوائر الاستئنافية ودوائر الجنايات الاقتصادية بدرجتيها بالمحاكم الاقتصادية ، أن تستعين برأى من تراه من الخبراء المتخصصين المقيدين فى الجداول التى تعد لذلك بوزارة العدل ، ويتم القيد فى هذه الجداول بقرار من وزير العدل بناء على الطلبات التى تقدم من راغبى القيد أو ممن ترشحهم الغرف والاتحادات والجمعيات وغيرها من المنظمات المعنية بشئون المال والتجارة والصناعة .
ويصدر بشروط وإجراءات القيد والاستعانة بالخبراء المقيدين بالجداول قرار من وزير العدل .
ويتبع فى شأن تأديب الخبراء المقيدين بالجداول أحكام المرسوم بقانون رقم 96 لسنة 1952 بتنظيم الخبرة أمام جهات القضاء .
وتحدد هذه الدوائر ، بحسب الأحوال ، الأتعاب التى يتقاضاها الخبير ، وذلك وفقاً للقواعد والإجراءات التى يصدر بها قرار من وزير العدل .$m243$,'314e737363eea48984e5d6e247ce1ae0'),
(10,0,$m243$المادة 10$m243$,$m243$يكون الطعن فى الأحكام الصادرة من الدوائر الابتدائية بالمحاكم الاقتصادية أمام الدوائر الاستئنافية بتلك المحاكم دون غيرها ، كما يكون الطعن فى الأحكام الصادرة من دوائر جنايات أول درجة الاقتصادية أمام دوائر الجنايات الاقتصادية المستأنفة دون غيرها .
ويكون الطعن فى الأحكام والتظلم من الأوامر الصادرة من القاضى المنصوص عليه فى المادة (3) من هذا القانون أمام الدوائر الابتدائية بالمحاكم الاقتصادية دون غيرها .
ومع مراعاة أحكام المادة (5) من هذا القانون يكون ميعاد استئناف الأحكام الصادرة فى الدعاوى التى تختص بها الدوائر الابتدائية بالمحكمة الاقتصادية أربعين يوماً من تاريخ صدور الحكم ، وذلك فيما عدا الأحكام الصادرة فى المواد المستعجلة ، والطعون المقامة من النيابة العامة .$m243$,'b429f9a7d396594d33985b63237a5173'),
(11,0,$m243$المادة 11$m243$,$m243$فيما عدا الأحكام الصادرة فى مواد الجنايات والجنح ، والأحكام الصادرة ابتداءً من الدوائر الاستئنافية بالمحكمة الاقتصادية ، لا يجوز الطعن فى الأحكام الصادرة من المحكمة الاقتصادية بطريق النقض ، دون إخلال بحكم المادة (250) من قانون المرافعات المدنية والتجارية .$m243$,'57c566583577b59fc8d9c9b5721efa95'),
(12,0,$m243$المادة 12$m243$,$m243$تشكل بمحكمة النقض دائرة أو أكثر تختص ، دون غيرها ، بالفصل فى الطعون بالنقض فى الأحكام المنصوص عليها فى المادة (11) من هذا القانون .
كما تنشأ بمحكمة النقض دائرة أو أكثر لفحص تلك الطعون ، تتكون كل منها من ثلاثة من قضاة المحكمة بدرجة نائب رئيس على الأقل ، لتفصل ، منعقدة فى غرفة المشورة ، فيما يفصح من الطعون عن عدم جوازه أو عن عدم قبوله لسقوطه أو لبطلان إجراءاته .
ويعرض الطعن ، فور إيداع نيابة النقض مذكرة برأيها ، على دائرة فحص الطعون ، فإذا رأت أن الطعن غير جائز أو غير مقبول ، للأسباب الواردة فى الفقرة السابقة ، أمرت بعدم قبوله بقرار مسبب تسبيباً موجزاً ، وألزمت الطاعن المصروفات فضلاً عن مصادرة الكفالة إن كان لذلك مقتضى ، وإذا رأت أن الطعن جدير بالنظر أحالته إلى الدائرة المختصة مع تحديد جلسة لنظره .
وفى جميع الأحوال لا يجوز الطعن فى القرار الصادر من دائرة فحص الطعون بأى طريق .
واستثناءً من أحكام المادة (39) من قانون حالات وإجراءات الطعن أمام محكمة النقض ، وأحكام الفقرة الثانية من المادة (269) من قانون المرافعات المدنية والتجارية ، إذا قضت محكمة النقض بنقض الحكم المطعون فيه حكمت فى موضوع الدعوى ولوكان الطعن لأول مرة .$m243$,'85d1d83e9c0cd9434141e7ee74921358'),
(13,0,$m243$المادة 13$m243$,$m243$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
السجل الإلكترونى : السجل المعد إلكترونياً بالمحاكم الاقتصادية لقيد بيانات الأشخاص والجهات المنصوص عليها فى المادة (17) من هذا القانون ، ووسيلة التواصل معهم التى تمكن راغب الإعلان من إخطار الخصوم بالدعوى أو بالطلبات العارضة أو بالأحكام التمهيدية الصادرة فيها .
العنوان الإلكترونى المختار : الموطن الذى يحدده الأشخاص والجهات المبينة بهذا القانون لإعلانهم بجميع إجراءات الدعاوى المقامة إلكترونياً ، سواء تمثل فى بريد إلكترونى خاص بهم أو رقم هاتف أو غيرها من الوسائل التكنولوجية .
الإيداع الإلكترونى : وسيلة إقامة صحيفة الدعوى وقيدها ، وكذا الطلبات العارضة والإدخال والتدخل ، والتوقيع على صحفها توقيعاً إلكترونياً معتمداً وإيداع المستندات والمذكرات والتى تتم عبر الموقع المخصص لذلك بالمحكمة الاقتصادية المختصة .
الموقع الإلكترونى : موقع خاص بالمحكمة الاقتصادية المختصة والمخصص لإقامة وقيد وإعلان الدعاوى إلكترونياً .
رفع المستندات إلكترونياً : تحميل المستندات والمذكرات المقدمة من أطراف الدعوى على الموقع الإلكترونى للمحكمة الاقتصادية المختصة مع إمكانية حفظها واسترجاعها والاطلاع عليها ونسخها تمهيداً لإرفاقها بملف الدعوى .
المستند أو المحرر الإلكترونى : رسالة بيانات تتضمن معلومات تنشأ أو تدمج أو تخزن أو ترسل أو تستقبل ، كلياً أو جزئياً ، بوسيلة إلكترونية أو رقمية أو ضوئية أو بغيرها من الوسائل المشابهة .
السداد الإلكترونى : الوسيلة التى توفرها المؤسسات المالية المصرفية وغير المصرفية لسداد جميع رسوم استخدام خدمة التقاضى الإلكترونى بالمحاكم الاقتصادية والرسوم القضائية والدمغات المقررة لإقامة الدعاوى ، ومنها البطاقات المدفوعة مسبقاً (بطاقات السحب والائتمان) ، والحوالات المصرفية .
الصورة المنسوخة : الصورة المطبوعة من المحرر الإلكترونى التى تودع بملف الدعوى .
سير الدعوى إلكترونياً : مباشرة إجراءات التقاضى المقررة قانوناً عبر الموقع الإلكترونى المخصص لهذا الغرض .
الإعلان الإلكترونى : إعلان أطراف الدعوى بأى إجراء قانونى يتخذ حال إقامتها وأثناء سيرها وذلك عبر الموقع الإلكترونى أو بالعنوان الإلكترونى المختار .
طرق حماية إقامة وسير الدعوى إلكترونياً : إجراءات حماية مستندات الدعوى المقامة إلكترونياً والتى تهدف إلى تفادى تعديل أو تغيير أو تدمير ملفاتها ، سواء تم ذلك عمداً أو بغير عمد .
الجهات ذات الصلة : الجهات المعنية بتسيير منظومة التقاضى الإلكترونى بالمحاكم الاقتصادية ، ومنها وزارة العدل ، ووزارة الاتصالات وتكنولوجيا المعلومات ، ووزارة الاستثمار والتعاون الدولى ، والهيئة العامة للاستثمار والمناطق الحرة ، والهيئة العامة للرقابة المالية ، والبورصة المصرية ، والبنك المركزى المصرى ، والسجل التجارى .$m243$,'4d843eb6e13a6e48cd3270f8128a18f9'),
(14,0,$m243$المادة 14$m243$,$m243$فيما عدا حالات الطعن بالنقض ، يجوز إقامة الدعاوى التى تختص بها المحكمة الاقتصادية والطعن على الأحكام الصادر فيها من الأشخاص والجهات المقيدة بالسجل الإلكترونى وذلك بموجب صحيفة موقعة ومودعة إلكترونياً بالموقع المخصص لقلم كتاب المحكمة الاقتصادية المختصة .
وتقيد الدعوى بعد سداد المدعى الرسوم والدمغات المقررة قانوناً إلكترونياً ورفع المستندات إلكترونياً .
ويفرض رسم لا يقل عن مائة جنيه ولا يجاوز ألف جنيه نظير استخدام تلك الخدمة الإلكترونية طبقاً للفئات التى يصدر بها قرار من وزير العدل ، وتئول حصيلة هذا الرسم إلى الإيرادات العامة لموازنة المحكمة الاقتصادية ، وتتحمل الموازنة العامة للدولة تكاليف إنشاء وتشغيل الموقع الإلكترونى لهذه الخدمة .$m243$,'0bee02906ff5e268879dc5c6cb54d6ba'),
(15,0,$m243$المادة 15$m243$,$m243$يرسل قلم الكتاب ملف الدعوى إلكترونياً إلى هيئة التحضير ، ويتولى قاضى التحضير مباشرة أعمال التحضير والوساطة المنصوص عليها فى هذا القانون ، وله فى سبيل ذلك تكليف أطراف الدعوى بالمثول أمامه متى رأى حاجة لذلك .$m243$,'12cc756187256e7bf441ae4170b120d0'),
(16,0,$m243$المادة 16$m243$,$m243$يعلن أطراف الدعوى المقامة إلكترونياً الخصوم بصحيفتها وطلباتها العارضة والإدخال على العنوان الإلكترونى المختار ، فإذا تعذر ذلك اتبع الطريق المعتاد للإعلان بقانون المرافعات المدنية والتجارية ، وفى هذه الحالة يلتزم قلم الكتاب بتسليم الصورة المنسوخة من صحيفة الدعوى أو الطلبات العارضة أو الإدخال فى اليوم التالى على الأكثر بعد تذييلها بخاتم شعار الجمهورية إلى قلم المحضرين التابع للمحكمة الاقتصادية المختصة لإعلانها وردها لإيداعها ملف الدعوى الورقى ، وفى جميع الأحوال ، على قلم الكتاب نسخ صورة المستند أو المحرر الإلكترونى وإيداعه ملف الدعوى الورقى .$m243$,'b87c4fe3dae09bd0a0318f90d984fecd'),
(17,0,$m243$المادة 17$m243$,$m243$مع عدم الإخلال بأحكام أى قانون آخر ، يلتزم المخاطبون بأحكام هذا القانون بتحديد عنوان إلكترونى مختار يتم الإعلان من خلاله ، وينشأ بالمحاكم الاقتصادية سجل إلكترونى موحد يخصص لقيد العنوان الإلكترونى المختار ، ومنه البريد الإلكترونى الخاص بالجهات والأشخاص الآتية :
1 - الدولة أو أحد الأشخاص الاعتبارية العامة .
2 - الشركات المحلية والأجنبية أو أحد الأشخاص الاعتبارية الخاصة .
3 - مكاتب المحامين .
وتوافى الجهات والأشخاص المشار إليها بالفقرة الأولى من هذه المادة المحاكم الاقتصادية بعنوانها الإلكترونى المختار لقيده فى ذلك السجل ، كما يجوز للأشخاص الطبيعية القيد بهذا السجل ، ويعد ذلك العنوان محلاً مختاراً لهم .
ومع ذلك ، يكون لذوى الشأن الاتفاق على أن يتم الإعلان على أى عنوان إلكترونى مختار آخر ، على أن يكون ذلك العنوان قابلاً لحفظه واستخراجه .$m243$,'7378bc204562f0f38f5899f6bc08a7f6'),
(18,0,$m243$المادة 18$m243$,$m243$يتم الإعلان الإلكترونى بإعلان الدعوى على الموقع الإلكترونى قبل تاريخ الجلسة المحددة بخمسة أيام عمل على الأقل ، وبإعلان الدولة على العنوان الإلكترونى المختار الخاص بفرع هيئة قضايا الدولة المختص محلياً ، وبالإعلان بذات الوسيلة على مكاتب المحامين المقيدين بالسجل إذا اتخذ منه المعلن إليه محلاً مختاراً له ، ويعتبر الإعلان الإلكترونى منتجاً لأثره فى الإعلان متى ثبت إرساله .$m243$,'084118897f3001d892e7865f0df5df19'),
(19,0,$m243$المادة 19$m243$,$m243$يجوز للخصوم إيداع المذكرات وتقديم المستندات وإبداء الدفاع والطلبات والاطلاع على أوراق الدعوى بالطريق الإلكترونى عبر الموقع الإلكترونى المخصص لذلك .$m243$,'e7727005516e900bc539c5b860114ceb'),
(20,0,$m243$المادة 20$m243$,$m243$إذا لم يحضر المدعى جلسات المحاكمة جاز للمحكمة إعمال نص المادة (82) من قانون المرافعات المدنية والتجارية .$m243$,'230aba4ef84a97933c53f4415db4aeca'),
(21,0,$m243$المادة 21$m243$,$m243$إذا أقيمت الدعوى بالطريق الإلكترونى ، جاز لقلم الكتاب إعلان الخصوم بالأحكام والقرارات التى تصدر أثناء سير الدعوى ولا تنتهى بها الخصومة بذات الطريق .$m243$,'da3aa3683645a27f69d3bb29894575c1'),
(22,0,$m243$المادة 22$m243$,$m243$إذا حضر المدعى عليه فى أى جلسة أو رفع المستندات والمذكرات إلكترونياً اعتبر الحكم المنهى للخصومة حضورياً فى مواجهته .$m243$,'f101b0ad886b90b1d57cfa07099e8fcb');

INSERT INTO m243_ver VALUES
(0,0,1,$m243$قانون رقم 120 لسنة 2008 بإصدار قانون بإنشاء المحاكم الاقتصادية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب ووافق مجلس الشورى على القانون الآتى نصه ، وقد أصدرناه :$m243$,'4d733fe0251db73a6df3e195fe5b01ce',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m243$يعمل بأحكام القانون المرافق فى شأن المحاكم الاقتصادية ، ولا يسرى فى شأنه أى حكم يخالف أحكامه .$m243$,'10c6f57fc14a0c3da5b7abe3ff7eb037',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m243$تحيل المحاكم من تلقاء نفسها ما يوجد لديها من منازعات ودعاوى أصبحت بمقتضى أحكام القانون المرافق من اختصاص المحاكم الاقتصادية وذلك بالحالة التى تكون عليها وبدون رسوم ، وفى حالة غياب أحد الخصوم يقوم قلم الكتاب بإعلانه بأمر الإحالة مع تكليفه بالحضور فى الميعاد أمام المحكمة التى تحال إليها الدعوى .
وتفصل المحاكم الاقتصادية فيما يحال إليها تطبيقاً لأحكام الفقرة السابقة دون عرضها على هيئة التحضير المنصوص عليها فى المادة (8) من القانون المرافق .
ولا تسرى أحكام الفقرة الأولى على المنازعات والدعاوى المحكوم فيها ، أو المؤجلة للنطق بالحكم قبل تاريخ العمل بهذا القانون ، وتبقى الأحكام الصادرة فيها خاضعة للقواعد المنظمة لطرق الطعن السارية فى تاريخ صدورها .$m243$,'981b258b71f3c8172ba08b22b29c9e18',DATE '2008-10-01',DATE '2019-09-30','amended',146,2019,$m243$النص الأصلى كما صدر بالقانون رقم 120 لسنة 2008 (الجريدة الرسمية العدد 21 (تابع) فى 22/5/2008؛ العمل به 1/10/2008)، قبل استبداله بالقانون رقم 146 لسنة 2019.$m243$),
(2,-1,2,$m243$تحيل المحاكم من تلقاء نفسها ما يوجد لديها من منازعات ودعاوى أصبحت بمقتضى أحكام هذا القانون من اختصاص المحاكم الاقتصادية وذلك بالحالة التى تكون عليها وبدون رسوم ، وفى حالة غياب أحد الخصوم يقوم قلم الكتاب بإعلانه بأمر الإحالة مع تكليفه بالحضور فى الميعاد أمام المحكمة التى أحيلت إليها الدعوى .
وتفصل المحاكم الاقتصادية فيما يحال إليها تطبيقاً لأحكام الفقرة السابقة دون عرضها على هيئة التحضير والوساطة المنصوص عليها فى المادة (8) من القانون المرافق .
كما تحال الطعون التى أصبحت من اختصاص المحاكم المنصوص عليها فى المادة (12) من هذا القانون إلى تلك المحاكم الأخيرة ، وذلك بالحالة التى تكون عليها .
ولا تسرى أحكام الفقرتين الأولى والثالثة من هذه المادة على المنازعات والدعاوى والطعون المحكوم فيها ، أو المؤجلة للنطق بالحكم قبل تاريخ العمل بهذا القانون ، وتبقى الأحكام الصادرة فيها خاضعة للقواعد المنظمة لطرق الطعن السارية فى تاريخ صدورها .$m243$,'224c93aecd83ee73d37923d1552ff86d',DATE '2019-10-01',NULL,'active',146,2019,$m243$النص بعد استبداله بالقانون رقم 146 لسنة 2019 (الجريدة الرسمية العدد 31 مكرر (و) فى 7/8/2019؛ العمل به 1/10/2019).$m243$),
(3,-1,1,$m243$تستمر محكمة النقض ومحاكم الاستئناف والدوائر الاستئنافية فى المحاكم الابتدائية فى نظر الطعون المرفوعة أمامها ، قبل تاريخ العمل بهذا القانون ، عن الأحكام الصادرة فى المنازعات والدعاوى المشار إليها فى الفقرة الأولى من المادة الثانية .$m243$,'f5989224972fb0fb49945ea4fca80066',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(4,-1,1,$m243$تطبق أحكام قوانين الإجراءات الجنائية ، وحالات وإجراءات الطعن أمام محكمة النقض ، والمرافعات المدنية والتجارية والإثبات فى المواد المدنية والتجارية، وذلك فيما لم يرد بشأنه نص خاص فى القانون المرافق .$m243$,'b39b587f94e1a5c3765e569a2093a188',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(5,-1,1,$m243$يصدر وزير العدل القرارات اللازمة لتنفيذ أحكام القانون المرافق .$m243$,'220a5c5e989733f9d719e89b87a4d5ca',DATE '2008-10-01',DATE '2019-09-30','amended',146,2019,$m243$النص الأصلى كما صدر بالقانون رقم 120 لسنة 2008 (الجريدة الرسمية العدد 21 (تابع) فى 22/5/2008؛ العمل به 1/10/2008)، قبل استبداله بالقانون رقم 146 لسنة 2019.$m243$),
(5,-1,2,$m243$يصدر وزير العدل ، بالتنسيق مع وزير الاتصالات وتكنولوجيا المعلومات ، القرارات المنظمة للقيد فى السجل المشار إليه فى المادة (17) من القانون المرافق وتنظيم إقامة وسير الدعوى إلكترونياً وإعلانها وطرق حمايتها وربط المحاكم الاقتصادية إلكترونياً ، وتلتزم الجهات ذات الصلة بتنفيذها .
كما يصدر وزير العدل ، بناءً على الطلبات التى تقدم من راغبى القيد ممن ترشحهم الجهات الرقابية المختصة أو الغرف والاتحادات والجمعيات وغيرها من الكيانات المعنية بشئون المال والتجارة والصناعة ، قراراً ينظم القيد فى الجداول المشار إليها فى الفقرة الثانية من المادة (8) من هذا القانون .$m243$,'c92f4a0096a81d6e1ba84a78b6029057',DATE '2019-10-01',NULL,'active',146,2019,$m243$النص بعد استبداله بالقانون رقم 146 لسنة 2019 (الجريدة الرسمية العدد 31 مكرر (و) فى 7/8/2019؛ العمل به 1/10/2019).$m243$),
(6,-1,1,$m243$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتباراً من أول أكتوبر سنة 2008
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 17 جمادى الأولى سنة 1429 هـ .
(الموافق 22 مايو سنة 2008 م) .
حسنى مبارك$m243$,'4f602a40ccb6e5f8750a23e135831efb',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m243$تنشأ بدائرة اختصاص كل محكمة استئناف محكمة تسمى «المحكمة الاقتصادية» ينتدب لرئاستها رئيس بمحاكم الاستئناف لمدة سنة قابلة للتجديد بقرار من وزير العدل بعد موافقة مجلس القضاء الأعلى ، ويكون قضاتها من بين قضاة المحاكم الابتدائية ومحاكم الاستئناف يصدر باختيارهم قرار من مجلس القضاء الأعلى .
وتتشكل المحكمة الاقتصادية من دوائر ابتدائية ودوائر استئنافية ، ويصدر بتعيين مقار هذه الدوائر قرار من وزير العدل بعد أخذ رأى مجلس القضاء الأعلى .
وتنعقد الدوائر الابتدائية والاستئنافية المنصوص عليها فى الفقرة السابقة فى مقار المحاكم الاقتصادية ، ويجوز أن تنعقد ، عند الضرورة ، فى أى مكان آخر وذلك بقرار من وزير العدل بناءً على طلب رئيس المحكمة الاقتصادية .$m243$,'08501fbebfaa5843cc5f4c73d57c6969',DATE '2008-10-01',DATE '2024-07-10','amended',156,2024,$m243$النص الأصلى كما صدر بالقانون رقم 120 لسنة 2008 (الجريدة الرسمية العدد 21 (تابع) فى 22/5/2008؛ العمل به 1/10/2008)، قبل استبداله بالقانون رقم 156 لسنة 2024.$m243$),
(1,0,2,$m243$تنشأ بدائرة اختصاص كل محكمة استئناف محكمة تسمى «المحكمة الاقتصادية» ينتدب لرئاستها رئيس بمحاكم الاستئناف لمدة سنة قابلة للتجديد بقرار من وزير العدل بعد موافقة مجلس القضاء الأعلى ، ويكون قضاتها من بين قضاة المحاكم الابتدائية ومحاكم الاستئناف يصدر باختيارهم قرار من مجلس القضاء الأعلى .
وتتشكل المحكمة الاقتصادية من دوائر ابتدائية ودوائر استئنافية ودوائر الجنايات الاقتصادية بدرجتيها ، ويصدر بتعيين مقار هذه الدوائر قرار من وزير العدل بعد أخذ رأى مجلس القضاء الأعلى .
وتنعقد الدوائر الابتدائية والاستئنافية ودوائر الجنايات الاقتصادية بدرجتيها المنصوص عليها فى الفقرة السابقة فى مقار المحاكم الاقتصادية ، ويجوز أن تنعقد ، عند الضرورة ، فى أى مكان آخر وذلك بقرار من وزير العدل بناءً على طلب رئيس المحكمة الاقتصادية .$m243$,'547cffbd32e456ec9f64f9b2c97816be',DATE '2024-07-11',NULL,'active',156,2024,$m243$النص بعد استبداله بالقانون رقم 156 لسنة 2024 (الجريدة الرسمية العدد 27 مكرر (د) فى 10/7/2024؛ العمل به 11/7/2024). أضيفت عبارة «ودوائر الجنايات الاقتصادية بدرجتيها» فى الفقرتين الثانية والثالثة.$m243$),
(2,0,1,$m243$تشكل كل دائرة من الدوائر الابتدائية الاقتصادية من ثلاثة من الرؤساء بالمحاكم الابتدائية .
وتشكل كل دائرة من الدوائر الاستئنافية من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة رئيس بمحكمة الاستئناف .$m243$,'4d638245b7ae56286ad5bce0b068b7c4',DATE '2008-10-01',DATE '2024-07-10','amended',156,2024,$m243$النص الأصلى كما صدر بالقانون رقم 120 لسنة 2008 (الجريدة الرسمية العدد 21 (تابع) فى 22/5/2008؛ العمل به 1/10/2008)، قبل استبداله بالقانون رقم 156 لسنة 2024.$m243$),
(2,0,2,$m243$تشكل كل دائرة من الدوائر الابتدائية الاقتصادية من ثلاثة من الرؤساء بالمحاكم الابتدائية .
وتشكل كل دائرة من الدوائر الاستئنافية من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة نائب رئيس بمحكمة الاستئناف .
وتشكل كل دائرة من دوائر جنايات أول درجة الاقتصادية من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة نائب رئيس بمحكمة الاستئناف .
كما تشكل كل دائرة من دوائر الجنايات الاقتصادية المستأنفة من ثلاثة من قضاة محاكم الاستئناف يكون أحدهم على الأقل بدرجة رئيس بمحكمة الاستئناف .$m243$,'6d7973a6ea1944db4cd007b6db113a88',DATE '2024-07-11',NULL,'active',156,2024,$m243$النص بعد استبداله بالقانون رقم 156 لسنة 2024 (الجريدة الرسمية العدد 27 مكرر (د) فى 10/7/2024؛ العمل به 11/7/2024). أضيفت فقرتان لتشكيل دوائر الجنايات الاقتصادية بدرجتيها، وعُدل مؤهل أحد قضاة الدائرة الاستئنافية من «رئيس» إلى «نائب رئيس بمحكمة الاستئناف».$m243$),
(3,0,1,$m243$تعين الجمعية العامة للمحكمة الاقتصادية ، فى بداية كل عام قضائى ، قاضياً أو أكثر من قضاتها بدرجة رئيس بالمحاكم الابتدائية من الفئة (أ) على الأقل ، ليحكم ، بصفة مؤقتة ومع عدم المساس بأصل الحق ، فى المسائل المستعجلة التى يخشى عليها من فوات الوقت والتى تختص بها تلك المحكمة .
ويصدر القاضى المشار إليه فى الفقرة الأولى الأوامر على عرائض والأوامر الوقتية ، وذلك فى المسائل التى تختص بها المحكمة الاقتصادية .
كما يصدر ، وأياً كانت قيمة الحق محل الطلب ، أوامر الأداء فى تلك المسائل ، وفى حالة امتناعه يحدد جلسة لنظر الدعوى أمام إحدى الدوائر الابتدائية أو الاستئنافية بالمحكمة ، بحسب الأحوال .$m243$,'e1d36a9b5db86eb0151a683ad7ac2e82',DATE '2008-10-01',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m243$تختص الدوائر الابتدائية والاستئنافية بالمحاكم الاقتصادية ، دون غيرها ، نوعياً ومكانياً بنظر الدعاوى الجنائية الناشئة عن الجرائم المنصوص عليها فى القوانين الآتية :
1 - قانون العقوبات فى شأن جرائم التفالس .
2 - قانون الإشراف والرقابة على التأمين فى مصر .
3 - قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة .
4 - قانون سوق رأس المال .
5 - قانون ضمانات وحوافز الاستثمار .
6 - قانون التأجير التمويلى .
7 - قانون الإيداع والقيد المركزى للأوراق المالية .
8 - قانون التمويل العقارى .
9 - قانون حماية حقوق الملكية الفكرية .
10 - قانون البنك المركزى والجهاز المصرفى والنقد .
11 - قانون الشركات العاملة فى مجال تلقى الأموال لاستثمارها .
12 - قانون التجارة فى شأن جرائم الصلح الواقى من الإفلاس .
13 - قانون حماية الاقتصاد القومى من الآثار الناجمة عن الممارسات الضارة فى التجارة الدولية .
14 - قانون حماية المنافسة ومنع الممارسات الاحتكارية .
15 - قانون حماية المستهلك .
16 - قانون تنظيم الاتصالات .
17 - قانون تنظيم التوقيع الإلكترونى وإنشاء هيئة تنمية صناعة تكنولوجيا المعلومات .$m243$,'6b4a3a154c1d1d1da18853136dc992a5',DATE '2008-10-01',DATE '2019-09-30','amended',146,2019,$m243$النص الأصلى كما صدر بالقانون رقم 120 لسنة 2008 (الجريدة الرسمية العدد 21 (تابع) فى 22/5/2008؛ العمل به 1/10/2008)، قبل استبداله بالقانون رقم 146 لسنة 2019.$m243$),
